/** saleson.shop.catalog.CatalogMngMapper.insertLocgovFavItemMng */
MERGE INTO G_LOCGOV_FAV_ITEM_MNG
USING DB_ROOT
ON	(CATALOG_YEAR = #{catalogYear} AND CATALOG_NO = #{catalogNo} AND LOCGOV_CODE = #{locgovCode})
WHEN MATCHED THEN
	UPDATE SET LAST_UPDUSR_ID = #{userId}
			, LAST_UPDT_PNTTM = SYS_DATETIME
			, DELETE_YN = 'N'
			, ITEM_ID = #{itemId}
WHEN NOT MATCHED THEN
	INSERT	(
		LOCGOV_CODE
		, CATALOG_YEAR
		, CATALOG_NO
		, DELETE_YN
		, ITEM_ID
		, FRST_REGISTER_ID
		, LAST_UPDUSR_ID
	)
	VALUES	(
		#{locgovCode}
		, #{catalogYear}
		, #{catalogNo}
		, 'N'
		, #{itemId}
		, #{userId}
		, #{userId}
	)

