/** saleson.shop.catalog.CatalogMngMapper.selectLocgovFavItemMngCount */ SELECT COUNT(*) FROM ( SELECT LFIM.LOCGOV_CODE , LFIM.CATALOG_YEAR , LFIM.CATALOG_NO , LFIM.DELETE_YN , LFIM.FRST_REGIST_PNTTM , LFIM.LAST_UPDT_PNTTM , L.UPPER_LOCGOV_NM || '' || L.LOCGOV_NM AS LOCGOV_NM FROM G_LOCGOV_FAV_ITEM_MNG LFIM JOIN G_CATALOG_MNG CM ON LFIM.CATALOG_YEAR = CM.CATALOG_YEAR AND LFIM.CATALOG_NO = CM.CATALOG_NO LEFT OUTER JOIN G_LOCGOV L ON LFIM.LOCGOV_CODE = L.LOCGOV_CODE WHERE 1=1
AND LFIM.LOCGOV_CODE = #{locgovCode}
AND L.UPPER_LOCGOV_CODE = #{upperLocgovCode}
AND LFIM.DELETE_YN = #{deleteYn}ㄹ
AND LFIM.FRST_REGIST_PNTTM BETWEEN CONCAT(#{searchStartDate}, '000000') AND CONCAT(#{searchEndDate}, '235959')
AND LFIM.CATALOG_YEAR = #{catalogYear} AND LFIM.CATALOG_NO = #{catalogNo}
)

/** saleson.shop.catalog.CatalogMngMapper.selectLocgovFavItemMng */ SELECT LFIM.LOCGOV_CODE , LFIM.CATALOG_YEAR , LFIM.CATALOG_NO , LFIM.DELETE_YN , IFNULL(LFIM.ITEM_ID, 0) AS ITEM_ID , LFIM.FRST_REGIST_PNTTM , LFIM.LAST_UPDT_PNTTM , L.UPPER_LOCGOV_NM || ' ' || L.LOCGOV_NM as LOCGOV_NM , CM.DISPLAY_YN , I.ITEM_USER_CODE , IFNULL(I.SALE_PRICE, 0) AS SALE_PRICE , I.ITEM_NAME , I.ITEM_ID , I.ITEM_IMAGE , I.DATA_STATUS_CODE , I.DISPLAY_FLAG , I.ITEM_USER_CODE , I.ITEM_CODE FROM G_LOCGOV_FAV_ITEM_MNG LFIM JOIN G_CATALOG_MNG CM ON LFIM.CATALOG_YEAR = CM.CATALOG_YEAR AND LFIM.CATALOG_NO = CM.CATALOG_NO LEFT OUTER JOIN G_LOCGOV L ON LFIM.LOCGOV_CODE = L.LOCGOV_CODE LEFT OUTER JOIN OP_ITEM I ON I.ITEM_ID = LFIM.ITEM_ID WHERE 1=1
AND LFIM.LOCGOV_CODE = #{locgovCode}
AND L.UPPER_LOCGOV_CODE = #{upperLocgovCode}
AND LFIM.CATALOG_YEAR = #{catalogYear} AND LFIM.CATALOG_NO = #{catalogNo}

/** saleson.shop.catalog.CatalogMngMapper.selectNewRgstItemMngCount */ SELECT COUNT(*) FROM ( SELECT * FROM ( SELECT SUB_CATALOG_YEAR , SEARCH_START_MONTH , SEARCH_END_MONTH , I.CREATED_DATE FROM OP_ITEM I INNER JOIN OP_ITEM_CATEGORY IC ON I.ITEM_ID = IC.ITEM_ID INNER JOIN OP_CATEGORY C ON IC.CATEGORY_ID = C.CATEGORY_ID AND C.CATEGORY_FLAG = 'Y' INNER JOIN OP_CATEGORY_GROUP G ON C.CATEGORY_GROUP_ID = G.CATEGORY_GROUP_ID AND G.CATEGORY_GROUP_FLAG = 'Y' LEFT JOIN OP_ITEM_OPTION_SOLDOUT IOST ON I.ITEM_ID = IOST.ITEM_ID LEFT OUTER JOIN OP_SELLER S ON I.SELLER_ID = S.SELLER_ID AND S.STATUS_CODE = '2' LEFT OUTER JOIN G_LOCGOV L ON S.LOCGOV_CODE = L.LOCGOV_CODE LEFT OUTER JOIN ( SELECT SUB_CATALOG_YEAR , CASE WHEN 1 <= CATALOG_MONTH AND CATALOG_MONTH <= 3 THEN '01' WHEN 4 <= CATALOG_MONTH AND CATALOG_MONTH <= 6 THEN '04' WHEN 7 <= CATALOG_MONTH AND CATALOG_MONTH <= 9 THEN '07' WHEN 10 <= CATALOG_MONTH AND CATALOG_MONTH <= 12 THEN '10' ELSE '99' END AS SEARCH_START_MONTH , CASE WHEN 1 <= CATALOG_MONTH AND CATALOG_MONTH <= 3 THEN '03' WHEN 4 <= CATALOG_MONTH AND CATALOG_MONTH <= 6 THEN '06' WHEN 7 <= CATALOG_MONTH AND CATALOG_MONTH <= 9 THEN '09' WHEN 10 <= CATALOG_MONTH AND CATALOG_MONTH <= 12 THEN '12' ELSE '99' END AS SEARCH_END_MONTH FROM ( SELECT CAST(CATALOG_YEAR AS VARCHAR) AS SUB_CATALOG_YEAR , MONTH(FRST_REGIST_PNTTM) AS CATALOG_MONTH FROM G_CATALOG_MNG WHERE 1=1 AND CATALOG_YEAR = #{catalogYear} AND CATALOG_NO = #{catalogNo} AND DISPLAY_YN = 'Y' ) ) SUB ON 1=1 WHERE 1=1 AND I.DATA_STATUS_CODE = '1' AND I.DISPLAY_FLAG = 'Y' AND I.ITEM_DATA_TYPE = '1' AND I.ITEM_TYPE IN ('1', '3') AND I.PRIVATE_TYPE IN ('000')
AND L.LOCGOV_CODE = #{locgovCode}
AND L.UPPER_LOCGOV_CODE = #{upperLocgovCode}
GROUP BY I.ITEM_ID ) T_A WHERE 1=1 AND T_A.CREATED_DATE BETWEEN CONCAT(SUB_CATALOG_YEAR, SEARCH_START_MONTH, '01000000') AND CONCAT(SUB_CATALOG_YEAR, SEARCH_END_MONTH, '99999999') )

/** saleson.shop.catalog.CatalogMngMapper.selectSeasonCatalogItemMngCount */
SELECT COUNT(*) FROM ( SELECT * FROM ( SELECT I.ITEM_ID , CATALOG_MONTH , SFI.SEASON_FOOD_MONTH FROM OP_ITEM I JOIN G_SEASON_FOOD_ITEM SFI ON I.ITEM_ID = SFI.ITEM_ID INNER JOIN OP_ITEM_CATEGORY IC ON I.ITEM_ID = IC.ITEM_ID INNER JOIN OP_CATEGORY C ON IC.CATEGORY_ID = C.CATEGORY_ID AND C.CATEGORY_FLAG = 'Y' INNER JOIN OP_CATEGORY_GROUP G ON C.CATEGORY_GROUP_ID = G.CATEGORY_GROUP_ID AND G.CATEGORY_GROUP_FLAG = 'Y' LEFT JOIN OP_ITEM_OPTION_SOLDOUT IOST ON I.ITEM_ID = IOST.ITEM_ID LEFT OUTER JOIN OP_SELLER S ON I.SELLER_ID = S.SELLER_ID AND S.STATUS_CODE = '2' LEFT OUTER JOIN G_LOCGOV L ON S.LOCGOV_CODE = L.LOCGOV_CODE LEFT OUTER JOIN ( SELECT MONTH(FRST_REGIST_PNTTM) AS CATALOG_MONTH FROM G_CATALOG_MNG WHERE 1=1 AND CATALOG_YEAR = #{catalogYear} AND CATALOG_NO = #{catalogNo} AND DISPLAY_YN = 'Y' ) SUB ON 1=1 WHERE 1=1 AND I.DATA_STATUS_CODE = '1'
AND L.LOCGOV_CODE = #{locgovCode}
AND L.UPPER_LOCGOV_CODE = #{upperLocgovCode}
) T_A WHERE 1=1 AND CASE WHEN CATALOG_MONTH IN (1, 2, 3) THEN SEASON_FOOD_MONTH IN (3, 4, 5) WHEN CATALOG_MONTH IN (4, 5, 6) THEN SEASON_FOOD_MONTH IN (6, 7, 8) WHEN CATALOG_MONTH IN (7, 8, 9) THEN SEASON_FOOD_MONTH IN (9, 10, 11) WHEN CATALOG_MONTH IN (10, 11, 12) THEN SEASON_FOOD_MONTH IN (12, 1, 2) ELSE 0=1 END GROUP BY T_A.ITEM_ID )

