/** saleson.shop.catalog.CatalogMngMapper.selectCardNewsList */
SELECT T_A.* , T_A.USER_NAME AS NAME FROM ( SELECT CCNM.CARD_NEWS_ID
, CCNM.CATALOG_YEAR , CCNM.CATALOG_NO , CCNM.CARD_NEWS_SUBJECT , CCNM.CARD_NEWS_CN , CCNM.DELETE_YN , M.USER_NAME , CCNM.FRST_REGIST_PNTTM FROM G_CATALOG_CARD_NEWS_MNG CCNM LEFT OUTER JOIN OP_MANAGER M ON CCNM.FRST_REGISTER_ID = M.USER_ID WHERE 1=1 AND CCNM.DELETE_YN = 'N'
AND CCNM.CATALOG_YEAR = #{catalogYear} AND CCNM.CATALOG_NO = #{catalogNo}
AND CCNM.CARD_NEWS_SUBJECT LIKE CONCAT('%', #{searchKeyword}, '%')
AND CCNM.FRST_REGIST_PNTTM BETWEEN CONCAT(#{startDate}, '000000') AND CONCAT(#{endDate}, '235959')
