/* saleson.shop.catalog.CatalogMngMapper.selectCatalogContentMngList 소식지 컨텐츠 목록 조회 */
SELECT T_A.* , ROWNUM AS `ROW_NUMBER` FROM ( SELECT CCM.CATALOG_CONTENT_ID , CCM.CATALOG_YEAR , CCM.CATALOG_NO , CCM.CONTENT_TYPE , CCM.CONTENT_SUB_TYPE , CCM.CATALOG_CONTENT_SUBJECT
, CCM.CATALOG_CONTENT_CN
, CCM.THUMBNAIL_IMG_PATH , CCM.LOCGOV_CODE , L.UPPER_LOCGOV_CODE , L.UPPER_LOCGOV_NM , L.LOCGOV_NM , CCM.DISPLAY_YN , CCM.BANNER_YN , ROWNUM AS `ROW_NUMBER` , CCM.FRST_REGIST_PNTTM FROM G_CATALOG_CONTENT_MNG CCM JOIN G_CATALOG_MNG CM ON CCM.CATALOG_YEAR = CM.CATALOG_YEAR AND CCM.CATALOG_NO = CM.CATALOG_NO LEFT JOIN G_LOCGOV L ON L.LOCGOV_CODE = CCM.LOCGOV_CODE WHERE 1=1
AND CCM.DISPLAY_YN = 'Y' AND CM.DISPLAY_YN = 'Y'
AND CCM.LOCGOV_CODE = #{locgovCode}
AND L.UPPER_LOCGOV_CODE = #{upperLocgovCode}
AND CCM.CATALOG_CONTENT_SUBJECT LIKE CONCAT('%', #{searchKeyword}, '%')
AND CCM.CATALOG_YEAR = #{catalogYear}
AND CCM.DISPLAY_YN = 'Y'
AND CCM.BANNER_YN = 'Y'
ORDER BY CCM.CATALOG_CONTENT_ID ) T_A ORDER BY T_A.CATALOG_CONTENT_ID DESC

